function localTableName(code=''){let hash=0;for(const char of code)hash=(Math.imul(hash,31)+char.charCodeAt(0))>>>0;return localTableNames[hash%localTableNames.length];}
// Browsers can block storage in iframes such as Discord's; fall back to memory so the game still loads.
const storage=name=>{try{const area=window[name];area.getItem('forest-probe');return area;}catch{const memory=new Map();return {getItem:k=>memory.get(k)??null,setItem:(k,v)=>memory.set(k,String(v)),removeItem:k=>memory.delete(k)};}};
const sessionStore=storage('sessionStorage'),localStore=storage('localStorage');
let simpleCards=localStore.getItem('forest-simple-cards')!=='false';setSimpleCards(simpleCards);
let continuationCode='',continuationTurnName='',room=null,auth=sessionStore.getItem('forest-token'),saved=sessionStore.getItem('forest-code'),selection=new Set(),fieldSelection=new Set(),tables=[],passed=true,muted=localStore.getItem('forest-muted')!=='false',lowerVolume=localStore.getItem('forest-lower-volume')==='true',busy=false,panel=null,polling=false,handRulesExpanded=false,notificationExpiryTimer=null,resumeValidationTimer=null,resumeValidationRequest=0,effectSoundRevision=0;
let handLayout=[],layoutStamp=null,selectedMeld=null,newCards=null,magicStamp=null,magicHidden=false;
const WizardHat='<svg class="wizard-hat" viewBox="0 0 28 25" role="img" aria-label="Host"><path d="M16 1h6v3h-6l-2 4 6 11H5L9 8z" fill="#b94155"/><path d="M5 17h15v3h5v3H1v-3h4z" fill="#7b263d"/><path d="M7 15h12v3H7z" fill="#e37a83"/><path d="M13 8h2v2h-2z" fill="#f6d38d"/></svg>';
