const sylvanDiscardEffect=(c,turn=room?.state?.turns??0)=>c&&!c.joker&&Number(c.discardEffectUntilTurn)>turn?c.discardEffect||'':'';
const card=(c,extra='',disabled=false)=>{const info=animals[c.suit]||{name:'Joker',color:'#9f79bf',pale:'#d6bfdd'},arise=c.effectGlow==='arise'&&(c.effectGlowUntil||0)>Date.now();return `<button ${disabled?'disabled':''} class="card ${extra} ${c.joker?'joker':''} ${selection.has(c.id)?'selected':''} ${arise?'arise-effect-glow':''}" style="--ink:${info.color};--paper:${info.pale}" data-card="${c.id}" aria-label="${c.joker?'Joker'+(c.as?' as '+rankLabel(c.as.rank)+' of '+animals[c.as.suit].name:''):rankLabel(c.rank)+' of '+info.name}${arise?', Arise effect':''}" aria-pressed="${selection.has(c.id)}">${cardMarkup(c)}${c.joker&&c.as?`<span class="joker-value">${rankLabel(c.as.rank)} · ${animals[c.as.suit].name}</span>`:''}</button>`;};
function sylvanTerm(text,family){return `<span class="sylvan-${family}-term">${esc(text)}</span>`;}
function notice(s){const target=$('notice');if(room?.options.variant==='hunt-escape'){target.innerHTML=esc(s).replace(/\b(hunters?|prey)\b/gi,term=>sylvanTerm(term,/^hunter/i.test(term)?'hunter':'prey'));}else target.textContent=s;setTimeout(()=>target.textContent='',5000);}
function renderNotifications(){const region=$('notifications');if(!region)return;const notes=(room?.notifications||[]).filter(item=>item.expiresAt>Date.now());region.innerHTML=notes.map(item=>`<button class="leave-notification" data-notification-id="${esc(item.id)}">${esc(item.message)}</button>`).join('');region.querySelectorAll('[data-notification-id]').forEach(button=>button.onclick=()=>run(async()=>{const result=await api('notification-code',{id:button.dataset.notificationId});accept(result.room);try{await navigator.clipboard.writeText(result.snapshot);notice('Code copied.');}catch{continuationCode=result.snapshot;continuationTurnName=result.turnName||room.state.names[room.state.turn];closePanel(false);panel='resume';renderPanel();$('resume-code').focus();$('resume-code').select();notice('Select and copy the continuation code.');}}));if(notificationExpiryTimer)clearTimeout(notificationExpiryTimer);if(notes.length)notificationExpiryTimer=setTimeout(()=>{if(room){room.notifications=(room.notifications||[]).filter(item=>item.expiresAt>Date.now());renderNotifications();}},Math.max(0,Math.min(...notes.map(item=>item.expiresAt))-Date.now()+20));}
const playSound=createSoundPlayer({contextFactory:()=>{const Audio=window.AudioContext||window.webkitAudioContext;return Audio?new Audio():null;},isMuted:()=>muted,getVolume:()=>lowerVolume?0.1:1});
function sound(cue='action'){playSound(cue);}
function specialEffectSounds(before,after){const old=before?.log||[],next=after?.log||[];if(old.length>next.length||old.some((line,index)=>next[index]!==line))return[];return next.slice(old.length).map(line=>line.includes('Blaze drew')||line.includes('Blaze found no card')?'blaze':line.includes('Quench makes')?'quench':line.includes('Hurry (')?'hurry':line.includes('Evoke can close')||line.includes('Evoke found no face-up Pack')||line.includes('used Evoke to close')?'evoke':line.includes('Arise returned')?'arise':null).filter(Boolean);}
async function api(endpoint,data){const response=await fetch('/api/'+endpoint,{method:data?'POST':'GET',headers:{'Content-Type':'application/json',...(auth?{Authorization:'Bearer '+auth}:{})},...(data?{body:JSON.stringify({code:room?.code||saved,...(room?{revision:room.revision}:{}),...data})}:{})});if(response.status===204)return null;let value=null;try{value=await response.json();}catch{}if(!response.ok||!value){if(response.status===409&&value?.room&&room?.code===value.room.code)accept(value.room);const error=Error(value?.error||'The forest is unreachable right now.');error.status=response.status;throw error;}return value;}
async function run(fn,cue='action'){if(busy)return;busy=true;const before=room?.state,soundRevision=effectSoundRevision;try{await fn();if(soundRevision===effectSoundRevision)sound(turnFinished(before,room?.state)?'turn':cue);}catch(e){notice(e.message);}finally{busy=false;}}
function clearChoice(){selection.clear();fieldSelection.clear();selectedMeld=null;}
function enter(value){dragUpdates.clear();auth=value.token;room=value.room;saved=room.code;clearChoice();sessionStore.setItem('forest-token',auth);sessionStore.setItem('forest-code',saved);localStore.setItem('forest-name',room.players[room.you]);render();wakePoll();}
function modal(html){closePanel();$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function tableList(){return `<h3>Open tables</h3>${tables.length?tables.map(t=>`<button class="table-link" data-join="${t.code}"><b>${t.code.toUpperCase()}</b><small>${esc(t.host)} · ${t.count}/${t.seats} players</small><span>↗</span></button>`).join(''):'<p>No open tables yet. Create one!</p>'}`;}
function home(){return `<section class="welcome"><h1 class="magic-sentence">There is magic in these woods.</h1><div class="entry-panel"><form id="entry"><label>Your name<input id="name" maxlength="24" autocomplete="nickname" placeholder="Leave blank for a forest name" value="${esc(localStore.getItem('forest-name')||'')}"></label><button class="primary" type="submit">Create a table</button><div class="divider">or join your friends</div><label>Table code<input id="join-code" maxlength="22000" placeholder="Table code or continuation code" value="${esc(new URLSearchParams(location.search).get('table')||'')}"></label><button id="join" type="button" class="secondary">Join table</button></form><div class="open-tables">${tableList()}</div></div><a class="atelier-button" href="/atelier/index.html">Card Atelier</a></section>`;}
function sylvanProgress(s,player){if(!s.opened[player])return 'closed';const parties=s.melds.filter(m=>!m.closed&&m.owner===player&&m.kind==='set'&&m.cards.length>=3).length,paths=s.melds.filter(m=>!m.closed&&m.owner===player&&m.kind==='run'&&!(m.stalkedUntilTurn&&s.turns<m.stalkedUntilTurn)),longPaths=paths.filter(m=>m.cards.length>=5).length,shortPaths=paths.filter(m=>m.cards.length===4).length;if(!parties&&!longPaths&&!shortPaths)return 'open';const label=`${parties} ${parties===1?'Party':'Parties'} of 3+ · ${longPaths} unblocked 5+ card ${longPaths===1?'Path':'Paths'} · ${shortPaths} unblocked 4-card ${shortPaths===1?'Path':'Paths'}`;return `<span class="sylvan-score-indicators" role="img" aria-label="Open; ${label}" title="${label}">${Array.from({length:parties},()=>'<span class="sylvan-party-mark" aria-hidden="true">×</span>').join('')}${Array.from({length:longPaths},()=>'<span class="sylvan-track-mark" aria-hidden="true">↑</span>').join('')}${Array.from({length:shortPaths},()=>'<span class="sylvan-track-mark" aria-hidden="true">→</span>').join('')}</span>`;}
function players(){const s=room.state,host=room.you===room.host;return `<div class="players">${room.players.map((name,i)=>{
 const bot=room.seatTypes[i]==='bot',empty=!room.seated[i],own=s?(room.mode==='local'?!bot:i===room.you):i===room.you,display=s?s.names[i]:name||(room.mode==='local'?`Player ${i+1}`:'Empty seat');
 const kickable=!s&&host&&room.mode==='online'&&i!==room.host&&room.seatTypes[i]==='human'&&room.seated[i],spirit=s?.roles?.[i]?`<span class="spirit-indicator spirit-${s.roles[i]}">${s.roles[i]==='hunt'?'HUNT':'ESCAPE'}</span>`:'';
 return `<article data-player="${i}" class="player ${s&&i===s.turn&&s.winner===null?'active':''} ${empty?'empty':''}">${spirit}<strong>${i===room.host?WizardHat:bot?BotIcon:''}<span class="${own?'own-name':''}">${esc(display)}</span></strong><small>${s?`${s.hands[i].length} ${room.options.variant==='rummikub'?'tiles':'cards'} · ${room.options.variant==='hunt-escape'?sylvanProgress(s,i):(s.opened[i]?'open':'closed')}`:i===room.host?'Table host':bot?'Ready to play':room.mode==='local'?'On this screen':empty?'Waiting for a friend':'Ready to play'}</small>${!s&&host&&i!==room.host&&!room.seated[i]||!s&&host&&i!==room.host&&(bot||room.mode==='local')?`<div class="seat-actions"><button data-seat-type="${i}" data-type="human" class="${!bot?'chosen':''}" aria-label="Human in seat ${i+1}">Player</button><button data-seat-type="${i}" data-type="bot" class="${bot?'chosen':''}" aria-label="Bot in seat ${i+1}">${BotIcon}<span>Bot</span></button>${room.players.length>2?`<button data-remove-seat="${i}" aria-label="Remove seat ${i+1}">×</button>`:''}</div>`:''}${kickable?`<div class="seat-actions kick-actions"><button class="kick-player" data-kick-player="${i}" aria-label="Kick ${esc(display)}" title="Kick player">Kick ×</button></div>`:''}</article>`;
 }).filter((_,i)=>!room.resumePending||room.seated[i]).join('')}${!s&&host&&room.players.length<6?`<article class="player add-seat"><button data-add="human"><span>+</span> Add player</button><button data-add="bot"><span>+</span>${BotIcon}<span>Add bot</span></button></article>`:''}</div>`;}
function ruleSelect(id,label,values,value){return `<div class="rule-choice-row ${id==='aceSeriesValue'?'ace-series-rule':id==='firstLapDiscard'?'first-lap-discard-rule':''}"><span>${label}</span><div role="group" aria-label="${label}">${values.map(([v,text])=>`<button class="rule-choice ${String(v)===String(value)?'chosen':''}" data-rule="${id}" data-rule-value="${v}" aria-pressed="${String(v)===String(value)}">${text}</button>`).join('')}</div></div>`;}
function ruleCheck(id,label,value,note=''){return `<button class="rule-toggle ${value?'chosen':''}" data-rule="${id}" data-rule-value="${!value}" aria-pressed="${value}" ${note?`title="${note}"`:''}>${label}</button>`;}
function winRules(o,targets=[101,151,301,501]){const mode=o.winEnabled?o.winMode:'none';return `<section class="variant-setting-box"><h2>Win condition:</h2><div class="win-rule-choices">${[['none','None'],['round','Round victories'],['stacking','Stacking point scores']].map(([value,label])=>`<button class="rule-choice ${mode===value?'chosen':''}" data-win-mode="${value}" aria-pressed="${mode===value}">${label}</button>`).join('')}<span>Multi-round scoring:</span>${targets.map(n=>`<button class="rule-choice ${mode==='multi'&&o.winTarget===n?'chosen':''}" data-win-target="${n}" aria-pressed="${mode==='multi'&&o.winTarget===n}">≥${n}</button>`).join('')}</div></section>`;}
function aceRules(o){return `<div class="rule-choice-row ace-rules"><span>Aces:</span><div role="group" aria-label="Aces:">${[['low','A → 2 → 3'],['high','Q → E → A']].map(([value,label])=>{const selected=o.aceMode==='both'||o.aceMode===value;return `<button class="rule-choice ${selected?'chosen':''}" data-ace="${value}" aria-pressed="${selected}" ${o.aceMode===value?'disabled':''}><span class="ace-sequence">${label}</span></button>`;}).join('')}</div></div>`;}
function duplicateRules(o){return `<section class="variant-setting-box duplicate-settings"><h2>Dealing duplicates:</h2><div class="duplicate-options">${[['dealDuplicateLimit','Do not deal more than:'],['redealDuplicateLimit','Choice to re-deal: if more than:']].map(([key,label])=>`<div class="duplicate-choice"><span>${label}</span>${[3,4].map(n=>`<button class="rule-choice ${o[key]===n?'chosen':''}" data-rule="${key}" data-rule-value="${o[key]===n?0:n}" aria-pressed="${o[key]===n}">${n}</button>`).join('')}</div>`).join('')}</div></section>`;}
function publicInfoRules(o){return `<section class="variant-setting-box public-information-settings"><h2>Public information:</h2><div class="public-information-options">${ruleSelect('turnOver4Sets','Turn over 4-sets:',[[true,'Yes'],[false,'No']],o.turnOver4Sets)}${ruleSelect('publicDiscardPile','Public discard pile:',[[true,'Yes'],[false,'No']],o.publicDiscardPile)}</div></section>`;}
function tinkering(o){return `${classicRules(o)}<div class="starting-options"><h2>Starting cards: <span>${o.handSize}</span></h2><div class="card-count-picker" role="group" aria-label="Starting hand size">${Array.from({length:14},(_,i)=>i+1).map(n=>`<button class="count-card ${n<7?'fixed-minimum':n<=o.handSize?'included-card':''} ${n===o.handSize?'chosen':''}" data-count="${n}" aria-label="${n} starting cards${n<7?' — included minimum':''}" aria-pressed="${n===o.handSize}" ${n<7?'disabled':''}><span>${n}</span></button>`).join('')}</div><p class="rules-note">Seven cards minimum. First player gets one extra.</p></div><div class="core-rule-row four-rule-controls">${ruleSelect('opening','Opening:',[[31,'31'],[51,'51']],o.opening)}${ruleSelect('firstLapDiscard','First lap discard:',[['blocked','Not allowed'],['take-no-open','Take; no opening']],o.firstLapDiscard||'take-no-open')}${ruleSelect('jokerCount','Jokers in deck:',[[4,'4'],[8,'8']],o.jokerCount)}${aceRules(o)}${ruleSelect('aceSeriesValue','Ace in a series:',[['ten','10 points'],['one','1 in <span class="ace-sequence">A → 2 → 3</span>']],o.aceSeriesValue||'ten')}<div class="rule-choice-row direct-rule">${ruleCheck('jokerEnds','Jokers at run ends',o.jokerEnds)}</div><div class="rule-choice-row direct-rule"><button id="hand-rules-toggle" class="rule-toggle ${handRulesExpanded?'chosen':''}" aria-pressed="${handRulesExpanded}" aria-expanded="${handRulesExpanded}" aria-controls="hand-rule-settings">Finishing from hand</button></div></div><div id="hand-rule-settings" class="hand-rule-content finishing-settings" ${handRulesExpanded?'':'hidden'}><h2 class="finishing-rules-title">Rules of finishing from hand:</h2><p>Finish by opening and playing your own groups in one turn, keeping a final discard.</p><div class="finish-rule-buttons">${ruleCheck('handEnabled','Award a finishing-from-hand bonus',o.handEnabled)}${ruleCheck('handRequiresOpening',`Require at least ${o.opening} opening points`,o.handRequiresOpening)}${ruleCheck('handJokers','Allow jokers when finishing from hand',o.handJokers)}${ruleCheck('handDouble','Double other players’ penalties',o.handDouble)}${ruleCheck('cutEnabled','Allow finishing with the cut card',o.cutEnabled)}${ruleSelect('handBonus','Finishing bonus:',[[80,'−80'],[100,'−100']],o.handBonus)}${ruleSelect('cutBonus','Cut-card bonus:',[[120,'−120'],[140,'−140']],o.cutBonus)}</div></div>${winRules(o)}${duplicateRules(o)}${publicInfoRules(o)}`;}

function lobby(){const host=room.you===room.host,o={...DEFAULT_RULES,...room.options},tinker=room.tinkering,onlineGuest=room.mode==='online'&&room.players.some((_,i)=>i!==room.you&&room.seatTypes[i]==='human'&&room.seated[i]);return `<section class="lobby"><div class="lobby-title-row">${tinker?'<button id="tinker-back" class="text-button back-button">← Back</button>':'<span></span>'}<h1>${tinker?'Speak the truenames.':'The forest awaits.'}</h1><span></span></div><fieldset class="lobby-options ${tinker?'tinkering-slide':''}" ${host?'':'disabled'}>${tinker?(o.variant==='rummikub'?rummikubSettings(o):o.variant==='hunt-escape'?huntEscapeSettings(o):tinkering(o)):`<h2>Choose game mode:</h2><div class="modes">${[['online','Online play','Meet beneath the stars.',NightSkyIcon],['local','Local','Gather in the glade. Share a screen with friends and woodland bots.',ForestIcon]].map(([mode,title,desc,icon])=>`<button class="mode ${room.mode===mode?'chosen':''} ${mode==='local'&&host&&onlineGuest?'local-mode-blocked':''}" data-mode="${mode}" ${mode==='local'&&host&&onlineGuest?'disabled':''}><strong><span class="mode-icon">${icon}</span>${title}</strong><small>${desc}</small></button>`).join('')}</div><div class="rules-options"><h2>Choose game variant:</h2><div class="variant-row"><div class="variant-choices"><button class="${o.variant==='remi51'?'chosen':''}" id="classic" data-variant="remi51" aria-pressed="${o.variant==='remi51'}"><strong>Classic Rummy</strong><small>Serbian Remi</small></button><button class="${o.variant==='rummikub'?'chosen':''}" data-variant="rummikub" aria-pressed="${o.variant==='rummikub'}"><strong>Rummikub</strong><small>Reweave the shared table</small></button><div class="original-game-wrap"><span class="original-game-indicator">ORIGINAL GAME</span><button class="${o.variant==='hunt-escape'?'chosen':''}" data-variant="hunt-escape" aria-pressed="${o.variant==='hunt-escape'}"><strong>Sylvan Trail</strong><small>A spirit hunt with asymmetric victories.</small></button></div></div><p>More variants coming...</p></div></div><button id="tinker" class="grimoire-link">${Grimoire}<span>Tinker with the rules?</span></button>`}</fieldset>${!tinker&&room.mode==='local'?`<div class="local-names">${room.players.map((name,i)=>i>0&&room.seatTypes[i]==='human'?`<label class="second-name">${i===1?'Second player’s name':`Player ${i+1}’s name`}<input data-local-name="${i}" maxlength="24" placeholder="Leave blank for a forest name" value="${esc(name)}" ${host?'':'disabled'}></label>`:'').join('')}</div>`:''}<div class="lobby-actions">${host?`<button class="primary" id="start" ${tinker?'disabled':''}>Start game</button>`:'<p>Waiting for the host to start…</p>'}<button class="rose" id="lobby-leave">Leave table</button></div></section>`;}
function playerIndex(){return localPlayer(room);}
function layoutKey(){return `fablewood-packing:${room.code}:${room.round||0}:${room.dealNumber||0}:${playerIndex()}`;}
function saveLayout(){sessionStore.setItem(layoutKey()+':movement',JSON.stringify(handLayout));}
function saveNewCards(){if(layoutStamp&&newCards)sessionStore.setItem(layoutStamp+':new',JSON.stringify(newCards));}
function dismissNewCards(ids){newCards=acknowledgeCards(newCards,ids);saveNewCards();for(const shell of document.querySelectorAll('.hand-card-shell[data-new-card]'))if(ids.includes(shell.dataset.newCard)){shell.querySelector('.new-card-badge,.returned-card-badge')?.remove();shell.removeAttribute('data-new-card');}}
function syncLayout(hand){const key=layoutKey()+':movement';if(key!==layoutStamp){layoutStamp=key;try{handLayout=JSON.parse(sessionStore.getItem(key)||'[]');}catch{handLayout=[];}try{newCards=JSON.parse(sessionStore.getItem(key+':new')||'null');if(newCards&&(!Array.isArray(newCards.seen)||!Array.isArray(newCards.fresh)))newCards=null;}catch{newCards=null;}selection.clear();selectedMeld=null;}handLayout=snapSeries(reconcileLayout(handLayout,hand),hand,room.options);const ids=hand.map(c=>c.id),present=new Set(ids);const reserved=new Set((room.state.fieldGroups||[]).filter(g=>g.owner===playerIndex()).flatMap(g=>g.cards.map(c=>c.id)));selection=new Set([...selection].filter(id=>present.has(id)&&!reserved.has(id)));fieldSelection=new Set([...fieldSelection].filter(id=>reserved.has(id)));newCards=updateNewCards(newCards,ids);saveNewCards();saveLayout();}
function handCard(c,{group=false,field=null,editable=true}={}){const returned=newCards?.returned?.includes(c.id),fresh=!returned&&newCards?.fresh.includes(c.id),badge=field===null&&(returned||fresh),arise=c.effectGlow==='arise'&&(c.effectGlowUntil||0)>Date.now();return `<span class="hand-card-shell" ${badge?`data-new-card="${c.id}"`:''}>${card(c)}${arise?'<span class="card-effect-badge">Arise</span>':''}${badge?`<span class="card-status-badge ${returned?'returned-card-badge':'new-card-badge'}">${returned?'Returned':'New'}</span>`:''}${group&&editable?`<button class="eject-card" ${field===null?`data-eject-hand="${c.id}"`:`data-eject-field="${field}" data-eject-id="${c.id}"`} aria-label="${room.options.variant==='rummikub'&&field!==null?'Detach tile from group':'Return this card to your hand, ungrouped'}"><span>x</span></button>`:''}</span>`;}
