function syncStalkTracks(){const area=document.querySelector('.hunt-escape-game .meld-area');if(!area||!room?.state)return;const svg=area.querySelector('.stalk-tracks');if(!svg)return;const bounds=area.getBoundingClientRect(),width=Math.max(1,area.clientWidth),height=Math.max(1,area.clientHeight),melds=new Map([...area.querySelectorAll('[data-meld-id]')].map(el=>[el.dataset.meldId,el]));svg.setAttribute('viewBox',`0 0 ${width} ${height}`);const trails=[];for(const pathMeld of room.state.melds.filter(m=>m.stalkedFrom)){const party=melds.get(pathMeld.stalkedFrom),path=melds.get(pathMeld.id);if(!party||!path)continue;const a=party.getBoundingClientRect(),b=path.getBoundingClientRect(),ax=a.left+a.width/2-bounds.left,ay=a.top+a.height/2-bounds.top,bx=b.left+b.width/2-bounds.left,by=b.top+b.height/2-bounds.top,fromRight=bx>=ax,x1=fromRight?a.right-bounds.left:a.left-bounds.left,x2=fromRight?b.left-bounds.left:b.right-bounds.left,curve=(x1+x2)/2;const d=`M ${x1} ${ay} C ${curve} ${ay}, ${curve} ${by}, ${x2} ${by}`;trails.push(`<path class="stalk-trail-glow" d="${d}"></path><path class="stalk-trail" d="${d}"></path>`);}svg.innerHTML=trails.join('');}
