function closePanel(restoreFocus=true){const trigger=panel==='discards'?$('discard-history'):panel==='resume'?$('copy'):$(panel);panel=null;$('floating').hidden=true;$('floating').classList.remove('discard-panel');for(const id of ['timer','undo-settings','score','log','help','leave','discard-history','copy'])$(id)?.setAttribute('aria-expanded','false');if(restoreFocus&&trigger?.isConnected)trigger.focus({preventScroll:true});}
function togglePanel(name){if(panel===name){closePanel();return;}const keyboard=(name==='discards'?$('discard-history'):name==='resume'?$('copy'):$(name))?.matches(':focus-visible');closePanel(false);panel=name;renderPanel();if(keyboard)$('panel-close').focus({preventScroll:true});}
function renderPanel(){if(!room||panel==='undo-settings'&&room.phase!=='lobby'){closePanel(false);return;}const content=$('panel-content'),scrollTop=content.scrollTop,focusedCard=document.activeElement?.closest('.discard-history .card')?.dataset.card;const title={discards:'Discard pile',timer:'Turn timer','undo-settings':'Undo move',score:'Table scoreboard',log:'Game log',help:'How to play',leave:'Leave table',resume:'Continuation code'}[panel];$('panel-title').textContent=title;$('floating').hidden=false;$(panel==='discards'?'discard-history':panel==='resume'?'copy':panel)?.setAttribute('aria-expanded','true');$('floating').classList.toggle('discard-panel',panel==='discards');alignFloatingPanel();const host=room.you===room.host&&room.phase==='lobby';
 if(panel==='resume')$('panel-content').innerHTML=`<p>This code saves the table at the start of ${esc(continuationTurnName||room.state.names[room.state.turn])}’s turn, including the rules and scoreboard. Share it with the original players; each person joins with the exact name they used at the table.</p><label class="resume-code-label">Continuation code<textarea id="resume-code" readonly rows="5" spellcheck="false">${esc(continuationCode)}</textarea></label><button id="copy-resume-code" class="primary">Copy continuation code</button>`;
 if(panel==='timer')$('panel-content').innerHTML=`<div class="timer-options">${[[0,'No timer'],[30,'30 seconds'],[60,'1 minute'],[120,'2 minutes']].map(([n,label])=>`<button data-timer="${n}" class="${room.options.timer===n?'chosen':''}" ${room.you===room.host?'':'disabled'}>${label}</button>`).join('')}</div><p>The host can change the timer at any time. A new duration gives the current turn a fresh countdown. On timeout, a legal turn is completed automatically.</p>`;
 if(panel==='undo-settings')$('panel-content').innerHTML=`<div class="undo-options"><button data-undo="true" class="purple ${room.options.undo?'chosen':''}" ${host?'':'disabled'}>Enable Undo</button><button data-undo="false" class="rose ${!room.options.undo?'chosen':''}" ${host?'':'disabled'}>Disable undo</button></div><p>Undo your latest action using the move button above your hand.</p>`;
 if(panel==='score'&&!room.completedGames){$('panel-content').innerHTML='<p>Results appear after the first completed game.</p>';return;}
 if(panel==='score'){const names=room.state?.names||room.players,winners=cupWinners(room),roundOnly=room.options.winEnabled&&room.options.winMode==='round',scores=roundOnly?(room.roundResults?.at(-1)?.scores||room.totals):room.totals;$('panel-content').innerHTML=`<p>${roundOnly?'Last round’s scores.':'Cumulative round scores.'}</p><ol class="score-rows">${names.map((n,i)=>`<li><span>${winners.includes(i)?cupMarkup:''}${esc(n||'Empty seat')}</span><strong>${scores[i]||0}</strong></li>`).join('')}</ol>`;}


 if(panel==='discards')$('panel-content').innerHTML=discardPanel(room.state?.discard||[]);
 if(panel==='log')$('panel-content').innerHTML=`<ol>${(room.state?.log||['Waiting for the host.']).map(t=>'<li>'+esc(t)+'</li>').join('')}</ol>`;
 if(panel==='help')$('panel-content').innerHTML=room.options.variant==='rummikub'?rummikubRulesSummary(room.options):room.options.variant==='hunt-escape'?huntEscapeRulesSummary(room.options):classicRules(room.options);
 if(panel==='leave')$('panel-content').innerHTML=`<p>${room.mode==='online'?'A bot plays your seat for the rest of a running game. If you are the host, the next player becomes host. The table closes when its last player leaves.':'This closes the table and ends its game.'}</p><button id="confirm-leave" class="rose">Leave table</button>`;
 content.scrollTop=scrollTop;if(focusedCard)(content.querySelector(`[data-card="${focusedCard}"]`)||$('panel-close')).focus({preventScroll:true});
 document.querySelectorAll('[data-timer]').forEach(el=>el.onclick=()=>run(()=>update({timer:Number(el.dataset.timer)})));
 document.querySelectorAll('[data-undo]').forEach(el=>el.onclick=()=>run(()=>update({undo:el.dataset.undo==='true'})));
 if(panel==='resume')$('copy-resume-code').onclick=async()=>{try{await navigator.clipboard.writeText(continuationCode);notice('Continuation code copied.');}catch{$('resume-code').focus();$('resume-code').select();notice('Select and copy the continuation code.');}};
 if(panel==='leave')$('confirm-leave').onclick=()=>run(async()=>{await api('leave',{});dragUpdates.clear();room=null;auth=null;saved=null;sessionStore.removeItem('forest-code');sessionStore.removeItem('forest-token');closePanel(false);passed=true;clearChoice();render();});
}
function renderIndicators(){if(!room)return;$('timer-status').hidden=!room.options.timer;$('undo-status').hidden=room.options.undo;$('timer-status').innerHTML=ClockIcon+`<small id="timer-status-label">${room.options.timer?room.options.timer+' sec':'Off'}</small>`;$('timer-status').setAttribute('aria-label',room.options.timer?'Turn timer '+room.options.timer+' seconds':'Turn timer disabled');$('undo-status').innerHTML=UndoIcon+(room.options.undo?'':cross);$('undo-status').setAttribute('aria-label',room.options.undo?'Undo enabled':'Undo disabled');}
function renderSound(){$('sound').innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 17V5l11-2v12M9 9l11-2" fill="none" stroke="currentColor" stroke-width="2"/><path d="M3 16h6v5H3zm11-2h6v5h-6z" fill="currentColor"/>${muted?'<path d="M3 3l18 18" stroke="#ba4949" stroke-width="3"/>':''}</svg>`;$('sound').setAttribute('aria-label',muted?'Unmute sounds':'Mute sounds');$('sound').title=muted?'Unmute sounds':'Mute sounds';$('lower-volume').hidden=!room||room.phase!=='game'||muted;}
for(const[id,icon,label]of [['timer',ClockIcon,'Turn timer'],['undo-settings',UndoIcon,'Enable or disable Undo move'],['leave',LeaveIcon,'Leave table'],['log',ScrollIcon,'Game log']])$(id).innerHTML=icon+`<span class="control-label">${label}</span>`;
const gameTitle=document.querySelector('#header .brand');let titlePointerOn=false;gameTitle.addEventListener('pointerenter',()=>{titlePointerOn=true;gameTitle.classList.add('gold-glow-loop');});gameTitle.addEventListener('pointerleave',()=>{titlePointerOn=false;});gameTitle.addEventListener('animationiteration',e=>{if(e.animationName==='fablewood-title-glow'&&!titlePointerOn)gameTitle.classList.remove('gold-glow-loop');});
$('score').innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10v9l-3 3h-1v4h4v3H7v-3h4v-4h-1l-3-3V3zM7 5H3v5l4 3m10-8h4v5l-4 3" fill="none" stroke="currentColor" stroke-width="2"/></svg><span class="control-label">Table scoreboard</span>';
for(const id of ['timer','undo-settings','score','log'])$(id).onclick=()=>togglePanel(id);
$('panel-close').onclick=closePanel;$('close').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').close();};
function applySimpleCards(enabled){const name=$('name')?.value,code=$('join-code')?.value;simpleCards=enabled;setSimpleCards(simpleCards);render();if(!room){$('name').value=name??'';$('join-code').value=code??'';}}
$('simple-cards').onclick=()=>{if(room)return;localStore.setItem('forest-simple-cards',String(!simpleCards));applySimpleCards(!simpleCards);};$('simple-style').onclick=()=>{if(!room||room.phase!=='game'||room.options.variant==='rummikub')return;localStore.setItem('forest-simple-cards',String(!simpleCards));applySimpleCards(!simpleCards);};
window.addEventListener('storage',e=>{if(e.key==='forest-simple-cards')applySimpleCards(e.newValue==='true');});
$('sound').onclick=()=>{muted=!muted;localStore.setItem('forest-muted',muted);renderSound();sound();};$('lower-volume').onclick=()=>{lowerVolume=!lowerVolume;localStore.setItem('forest-lower-volume',String(lowerVolume));sound();render();};renderSound();
$('copy').onclick=()=>{if(!room||room.mode==='local')return;run(async()=>{if(room.phase==='game'){const result=await api('snapshot',{});continuationCode=result.snapshot;continuationTurnName=result.turnName;try{await navigator.clipboard.writeText(continuationCode);notice('Continuation code copied.');}catch{closePanel(false);panel='resume';renderPanel();$('resume-code').focus();$('resume-code').select();notice('Select and copy the continuation code.');}return;}try{await navigator.clipboard.writeText(room.code.toUpperCase());notice('Table code copied: '+room.code.toUpperCase());}catch{notice('Table code: '+room.code.toUpperCase());}});};
function leave(){togglePanel('leave');}
$('leave').onclick=leave;
$('help').onclick=()=>{if(room?.phase==='game')togglePanel('help');};

function tick(){document.querySelectorAll('[data-resume-countdown]').forEach(el=>{if(room?.resumeCountdownAt)el.textContent=Math.max(1,Math.ceil((room.resumeCountdownAt-Date.now())/1000))+'...';});if(room?.nextRoundAt)document.querySelectorAll('[data-round-countdown]').forEach(el=>{el.textContent='New round starting in '+Math.max(1,Math.ceil((room.nextRoundAt-Date.now())/1000))+'…';});const s=room?.state,el=$('timer-status-label');if(!el||!s||!room.options.timer||s.winner!==null)return;if(room.dealDecision){el.textContent='Paused';$('timer-status').classList.remove('urgent');return;}const left=Math.max(0,Math.ceil((s.turnStarted+room.options.timer*1000-Date.now())/1000));el.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');$('timer-status').classList.toggle('urgent',left<10);}
document.addEventListener('pointerdown',()=>{if(!muted)playSound.unlock();},{once:true,capture:true});
document.addEventListener('click',e=>{if(room?.phase==='game'&&(selection.size||fieldSelection.size)&&!e.target.closest('[data-card],[data-unit],[data-field-group]')){selection.clear();fieldSelection.clear();render();}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')){const trigger=panel==='discards'?'discard-history':panel;closePanel(false);clearChoice();if(room)render();if(trigger)$(trigger)?.focus({preventScroll:true});}});
setInterval(tick,500);
let failures=0,pollTimer=null,pollAgain=false;
async function poll(){
 if(polling)return;polling=true;let delay=0;const code=room?.code||saved;
 try{
  if(!room&&saved&&auth){accept(await api('state?code='+saved));}
  if(room){const next=await api('state?code='+room.code+'&since='+room.revision);if(room?.code===code&&next)accept(next);}
  else if(!document.hidden){const next=await api('tables');if(!room&&JSON.stringify(next)!==JSON.stringify(tables)){tables=next;const list=document.querySelector('.open-tables');if(list){list.innerHTML=tableList();list.querySelectorAll('[data-join]').forEach(el=>el.onclick=()=>join(el.dataset.join));}}delay=15000;}
  else delay=15000;
  failures=0;
 }catch(e){
  if(room?.code===code&&e.status===400){dragUpdates.clear();room=null;auth=null;saved=null;sessionStore.removeItem('forest-code');sessionStore.removeItem('forest-token');clearChoice();closePanel();render();notice(e.message);delay=15000;}
  else{delay=Math.min(30000,1200*2**failures++);if(failures===1&&room)notice('Connection lost. Reconnecting…');}
 }finally{polling=false;pollTimer=setTimeout(poll,pollAgain?0:delay);pollAgain=false;}
}
function wakePoll(){clearTimeout(pollTimer);if(polling)pollAgain=true;else poll();}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)wakePoll();});
render();
async function restore(){if(saved&&auth)try{accept(await api('state?code='+saved));}catch(e){if(e.status===400){sessionStore.removeItem('forest-code');sessionStore.removeItem('forest-token');saved=null;auth=null;}else notice('The forest is unreachable right now. Reconnecting…');}poll();}
restore();
